            shellHook = \'\'
            echo \"Добро пожаловать в среду разработки!\";
            # if [ -z \"\$DIRENV_IN_ENVRC\" ]; then
                # shellHook
            # fi
            \'\';
        };
        };
    }" > flake.nix
    string replace -a "\\'" "'" < flake.nix > flake.nix.new
